{
  "findings": [
    {
      "check_id": "AVD-AWS-0036",
      "title": "Sensitive environment variable in container definition",
      "resource": "aws_ecs_task_definition.service",
      "severity": "CRITICAL",
      "explanation": "The container definition contains a potentially sensitive environment variable 'DATABASE_PASSWORD' that could be exposed in the AWS Management Console."
    }
  ],
  "patched_code": "resource "aws_ecs_task_definition" "service" {
  family                = "service"
  container_definitions = jsonencode([
    {
      name        = "service"
      image       = "some-image"
      environment = [
        {
          name  = "DATABASE_PASSWORD"
          value = "${aws_secretsmanager_secret_version.db_password.secret_string}"
        }
      ]
    }
  ])

  volume {
    name = "efs-vol-1"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.fs1.id
      root_directory          = "/opt/data1"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
      authorization_config {
        access_point_id = aws_efs_access_point.test1.id
        iam             = "ENABLED"
      }
    }
  }

  volume {
    name = "efs-vol-2"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.fs2.id
      root_directory          = "/opt/data2"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
      authorization_config {
        access_point_id = aws_efs_access_point.test2.id
        iam             = "ENABLED"
      }
    }
  }
}",
  "fix_summary": "Replaced the file-based container_definitions with a jsonencode representation that uses SecretsManager for sensitive environment variables."
}
